import fs from 'node:fs';
import {createHash} from 'node:crypto';
import assert from 'node:assert/strict';
import sharp from 'sharp';
const read=name=>JSON.parse(fs.readFileSync(`data/${name}.json`,'utf8'));
const save=(name,value)=>fs.writeFileSync(`data/${name}.json`,JSON.stringify(value,null,2)+'\n');
const hash=file=>createHash('sha256').update(fs.readFileSync(file)).digest('hex');
const date='2026-11-20',manifest='data/wiki-tata-evidence-2026-11-20.json';
const id='hikoko',names=['ヒココ','ヒコケコ','ヒコケコッコ','フェニコケコッコ'],files=[2841,2842,2843,2848];
const url='https://w.atwiki.jp/monstersurvival/pages/189.html';
const db=read('tatari'),skills=read('tata-skills'),images=read('tata-images'),sources=read('tata-name-i18n-sources');
const trials=read('evolution-trials');
assert(!db.families.some(f=>f.id===id),'Do not overwrite an existing family');
const records=[],evolutions=[],forms=[],stages=[];
for(const [index,name] of names.entries()){
  const stage=index+1,recordId=`${id}:T${stage}`,base=`assets/tata-wiki/${id}/t${stage}`,original=base+'-source.webp';
  const metadata=await sharp(original).metadata(),sourceSha256=hash(original);
  for(const size of [256,512])await sharp(original).resize(size,size,{fit:'contain',background:{r:0,g:0,b:0,alpha:0}}).webp({lossless:true}).toFile(`${base}-${size}.webp`);
  const evidence={sourceType:'public_wiki_game_asset',manifest,recordId,sourceUrl:url,sourceSha256,checkedAt:date};
  records.push({recordId,familyId:id,stage,name,sourceUrl:url,imageUrl:`https://img.atwiki.jp/monstersurvival/attach/83/${files[index]}/${encodeURIComponent(name)}.webp`,originalPath:original,sourceSha256,originalWidth:metadata.width,originalHeight:metadata.height,checkedAt:date});
  evolutions.push({stage,name,nameEn:null,nameZhHans:null,image:base+'-512.webp',source:manifest,nameVerification:{en:'pending','zh-CN':'pending'},imageEvidence:evidence});
  forms.push({stage,name,src:`/${base}-512.webp`,srcset:`/${base}-256.webp 256w, /${base}-512.webp 512w`,sizes:'(max-width: 600px) 44vw, 256px',width:512,height:512,status:'verified',sha256:hash(base+'-512.webp'),sourceType:'public_wiki_game_asset',sourceSha256,sourceUrl:url,evidenceManifest:manifest,evidenceRecord:recordId,optimizedPath:`/${base}-512.webp`,verifiedAt:date});
  stages.push({stage,tataName:name,skillName:'確認待ち',description:'Wikiの名称と画像を確認済み。スキル名・効果・数値はゲーム内資料の確認待ちです。',values:[],sources:[],verificationStatus:'pending-wiki-skill-evidence',nameEn:null,nameZhHans:null,evidence:{sourceType:'public_wiki',sourceUrl:url,manifest,skillEvidenceProvided:false,verifiedAt:date}});
  sources.forms.push({familyId:id,stage,japaneseName:name,englishName:null,simplifiedChineseName:null,confidence:'pending-official',sourceType:'supplemental-evidence',japaneseEvidence:evidence,localizedEvidence:{en:{status:'pending',reason:'official-localized-name-not-obtained'},'zh-CN':{status:'pending',reason:'official-localized-name-not-obtained'}},checkedAt:date});
}
db.families.push({id,familyName:names[0],attribute:'火',attributeEvidence:{sourceType:'public_wiki',sourceUrl:url,checkedAt:date},verification:{namesAndImages:'public-wiki-confirmed',implementation:'general-release-not-independently-verified',checkedAt:date},evolutions,skills:stages.map(s=>({stage:s.stage,name:s.skillName,summary:s.description,stats:[],source:manifest})),searchAliases:names,tierMakerStages:[1,2,3,4]});
skills.byFamily[id]={familyId:id,familyName:names[0],attribute:'火',stages};
images.families.push({order:db.families.length,familyId:id,familyDisplay:names[0],attribute:'火',forms,stage1:forms[0]});
db.meta.familyCount=db.families.length;db.meta.monsterCount=db.families.reduce((n,f)=>n+f.evolutions.length,0);
db.meta.latestWikiSupplement={checkedAt:date,evidence:manifest,scope:[id]};
skills.totals.families=db.meta.familyCount;skills.totals.stages=skills.totals.skills=db.meta.monsterCount;
skills.totals.pendingSkillEvidence=Object.values(skills.byFamily).flatMap(f=>f.stages).filter(s=>/^pending-.*skill-evidence$/.test(s.verificationStatus||'')).length;
images.counts.families=db.meta.familyCount;images.counts.forms=db.meta.monsterCount;
images.counts.verifiedForms=images.families.flatMap(f=>f.forms).filter(f=>f.status==='verified').length;
images.counts.publicWikiGameAssetForms=images.families.flatMap(f=>f.forms).filter(f=>f.sourceType==='public_wiki_game_asset').length;
sources.summary.canonicalForms=db.meta.monsterCount;sources.summary.needsReview=sources.forms.filter(f=>f.confidence!=='confirmed').length;
trials.families.push({familyId:id,familyName:names[0],attribute:'火',conditions:names.slice(1).map((name,index)=>({stage:index+2,tataName:name,condition:'進化条件はゲーム内資料の確認待ち',status:'pending',needsHumanVerification:true,sourceType:'public_wiki_game_asset',sourceUrl:url,checkedAt:date,confirmedParts:[],pendingFields:['進化条件'],evidence:manifest}))});
trials.familyCount=trials.families.length;
save('wiki-tata-evidence-2026-11-20',{version:1,checkedAt:date,sourceUpdatedAt:'2026-11-18',sourceType:'public_wiki_game_asset',scope:'User-requested Hikoko game character artwork, Japanese evolution names and fire attribute only; no inferred localized names, skills or rankings.',rightsNote:'Wiki hosting is not evidence of a general redistribution license. Game artwork rights remain with their respective owners; these files are not official creator asset-pack records.',records});
save('tatari',db);save('tata-skills',skills);save('tata-images',images);save('tata-name-i18n-sources',sources);save('evolution-trials',trials);
console.log(`Added ${id}: four forms; ${db.meta.familyCount} families / ${db.meta.monsterCount} forms.`);
